            prev = ch; cnt = 1
    if prev is not None: out.append(f'{cnt}{prev}')
    rle = ''.join(out)
    if rle != e:
        print('MISMATCH:', repr(s), 'expected', repr(e), 'correct RLE', repr(rle))
print('done')
